import sysimport osimport numpy as npimport pandas as pdimport scanpy as scimport matplotlib.pyplot as pltfrom nsforest import ns, nsforesting, utils, NSFOREST_VERSIONdata_folder = "/Users/ggraham/MERFISH"file = "/Users/ggraham/MERFISH/obj.h5ad"adata = sc.read_h5ad(file)adatagenes = pd.read_csv("/Users/ggraham/MERFISH/2025_10_06_sparse_mat_rownames.csv")genes_to_keep = genes['x'].tolist()genes_present = [g for g in genes_to_keep if g in adata.var_names]adata = adata[:, genes_present].copy()adata.obs['final_clusters'] = np.where(adata.obs['final_clusters']==0, 'o', adata.obs['final_clusters'])adata.obs['final_clusters'] = adata.obs['final_clusters'].astype('category')adata = adata[adata.obs["final_clusters"].isin(["26", # dont care                                            "9", # poor classification quality                                            "20" # dont care                                            ]) == False]adata.obs['final_clusters'] = adata.obs['final_clusters'].astype('category')cluster_header = "final_clusters"#cluster_header2 = "final_clusters"output_folder = "/Users/ggraham/MERFISH/NSForest Output/"adata.obs_namesadata.var_namesadata.obs[cluster_header].value_counts()ns.pp.dendrogram(adata,                 cluster_header,                 save = True,                 output_folder = output_folder,                 outputfilename_suffix = cluster_header)#ns.pp.prep_mediansadata_subset = adata.copy()adata_subset = ns.pp.prep_medians(adata_subset, cluster_header)adata_subsetns.pp.prep_binary_scoresadata_subset = ns.pp.prep_binary_scores(adata_subset, cluster_header)adata_subsetplt.clf()filename = output_folder + cluster_header + '_medians.png'print(f"Saving median distributions as...\n{filename}")a = plt.figure(figsize = (6, 4))a = plt.hist(adata_subset.varm["medians_" + cluster_header].unstack(), bins = 100)a = plt.title(f'{file.split("/")[-1].replace(".h5ad", "")}: {"medians_" + cluster_header} histogram')a = plt.xlabel("medians_" + cluster_header)a = plt.yscale("log")a = plt.savefig(filename, bbox_inches='tight')plt.show()plt.clf()filename = output_folder + cluster_header + '_binary_scores.png'print(f"Saving binary_score distributions as...\n{filename}")a = plt.figure(figsize = (6, 4))a = plt.hist(adata_subset.varm["binary_scores_" + cluster_header].unstack(), bins = 100)a = plt.title(f'{file.split("/")[-1].replace(".h5ad", "")}: {"binary_scores_" + cluster_header} histogram')a = plt.xlabel("binary_scores_" + cluster_header)a = plt.yscale("log")a = plt.savefig(filename, bbox_inches='tight')plt.show()# Optional, can be useful if you don't want to re-run prep_medians and prep_binary_scoresfilename = file.replace(".h5ad", "_preprocessed.h5ad")print(f"Saving new anndata object as...\n{filename}")adata_subset.write_h5ad(filename)adata_subsetoutputfilename_prefix = cluster_headerresults = nsforesting.NSForest(adata_subset, cluster_header, save = True, save_supplementary = True,                               output_folder = output_folder, outputfilename_prefix = outputfilename_prefix)resultsns.pl.boxplot(results, "f_score", save = "html", output_folder = output_folder, outputfilename_prefix = outputfilename_prefix)ns.pl.boxplot(results, "f_score", save = True, output_folder = output_folder, outputfilename_prefix = outputfilename_prefix)ns.pl.boxplot(results, "precision", save = True, output_folder = output_folder, outputfilename_prefix = outputfilename_prefix)ns.pl.boxplot(results, "recall", save = True, output_folder = output_folder, outputfilename_prefix = outputfilename_prefix)ns.pl.boxplot(results, "onTarget", save = True, output_folder = output_folder, outputfilename_prefix = outputfilename_prefix)ns.pl.scatter_w_clusterSize(results, "f_score", save = True, output_folder = output_folder, outputfilename_prefix = outputfilename_prefix)ns.pl.scatter_w_clusterSize(results, "precision", save = True, output_folder = output_folder, outputfilename_prefix = outputfilename_prefix)ns.pl.scatter_w_clusterSize(results, "recall", save = True, output_folder = output_folder, outputfilename_prefix = outputfilename_prefix)ns.pl.scatter_w_clusterSize(results, "onTarget", save = True, output_folder = output_folder, outputfilename_prefix = outputfilename_prefix)adata.uns["dendrogram_" + cluster_header]["categories_ordered"]to_plot = results.copy()dendrogram = [] # custom dendrogram orderdendrogram = list(adata.uns["dendrogram_" + cluster_header]["categories_ordered"])to_plot["clusterName"] = to_plot["clusterName"].astype("category")to_plot["clusterName"] = to_plot["clusterName"].cat.set_categories(dendrogram)to_plot = to_plot.sort_values("clusterName")to_plot = to_plot.rename(columns = {"NSForest_markers": "markers"})to_plot.head()markers_dict = dict(zip(to_plot["clusterName"], to_plot["markers"]))markers_dictns.pl.dotplot(adata, markers_dict, cluster_header, dendrogram = dendrogram, save = True, output_folder = output_folder, outputfilename_suffix = outputfilename_prefix)ns.pl.stackedviolin(adata, markers_dict, cluster_header, dendrogram = dendrogram, save = True, output_folder = output_folder, outputfilename_suffix = outputfilename_prefix)ns.pl.matrixplot(adata, markers_dict, cluster_header, dendrogram = dendrogram, save = True, output_folder = output_folder, outputfilename_suffix = outputfilename_prefix)